def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    segments = [list(map(int, input().split())) for _ in range(m)]

    prefix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i-1] + a[i-1]

    max_diff = 0
    chosen_segments = []

    for i in range(m):
        l, r = segments[i]
        decrease = prefix_sum[r] - prefix_sum[l-1]

        if decrease > max_diff:
            max_diff = decrease
            chosen_segments = [i+1]
        elif decrease == max_diff and i+1 not in chosen_segments:
            chosen_segments.append(i+1)

    print(max_diff)
    print(len(chosen_segments))
    if chosen_segments:
        print(*chosen_segments)
    else:
        print()
